     "legenda": "E se eu pudesse voltar no tempo e pudesse decidir por não ter filhos?\n\nTalvez eu não tivesse a força, a coragem e a resiliência da mulher (mãe) que me tornei.\nAinda estou longe de ser a mãe perfeita, mas, se tem algo pelo qual eu luto todos os dias, é para me tornar a melhor mãe para os meus filhos. Eles são minha força, minha fortaleza e minha determinação. É por eles que eu não desisto.\n\nA minha história como mãe é linda, porque, mesmo com todas as dificuldades, eu decidi me doar com muito amor. E, mesmo depois de tudo que passei, quero construir uma história de muito amor e luta. Quero que eles sintam orgulho de mim.\n\nSer mãe é temer, é estar junto independentemente do que aconteça, é confiar, é plantar o amor e colher o melhor daquilo que eles podem oferecer.\n\nE, mesmo quando tudo dentro de mim parecer desabar, eu quero estar lá — apoiando na alegria e na tristeza — porque eles sempre precisarão de mim. Texto: Hellen Bentes",
     "tipo": "VIDEO",
